use hkia_save_core::{account::read_account,archive::{ZipIndex,crc32},digest::sha256,session::*,abi::*};
const ZIP:&[u8]=include_bytes!("fixtures/session-deflated.zip");const STORE:&[u8]=include_bytes!("fixtures/session-stored.zip");const ACCOUNT:&[u8]=include_bytes!("fixtures/session-account.json");const V300:&[u8]=include_bytes!("fixtures/valid-3.0.0.bin");const V301:&[u8]=include_bytes!("fixtures/valid-3.0.1.bin");
fn new()->ProductSession{ProductSession::new([3;16]).unwrap()}
fn send(s:&mut ProductSession,id:u64,command:Command)->Reply{let expected=s.stamp();s.dispatch(Request{id,expected,command})}
fn open(s:&mut ProductSession,id:u64,kind:InputKind,bytes:&[u8])->Reply{send(s,id,Command::Open{kind,bytes:bytes.to_vec()})}
fn frame(st:Stamp,id:u64,op:u8,rest:&[u8])->Vec<u8>{let mut b=Vec::new();b.extend(MAGIC);b.push(op);b.extend(id.to_le_bytes());b.extend(st.runtime);b.extend(st.generation.to_le_bytes());b.extend(st.revision.to_le_bytes());b.push(st.source.is_some()as u8);b.extend(st.source.unwrap_or([0;32]));b.extend(rest);b}
#[test]fn sha_vectors(){assert_eq!(sha256(b"abc"),[0xba,0x78,0x16,0xbf,0x8f,0x01,0xcf,0xea,0x41,0x41,0x40,0xde,0x5d,0xae,0x22,0x23,0xb0,0x03,0x61,0xa3,0x96,0x17,0x7a,0x9c,0xb4,0x10,0xff,0x61,0xf2,0x00,0x15,0xad]);assert_eq!(crc32(b"123456789"),0xcbf43926);}
#[test]fn zip_targets_stored(){let z=ZipIndex::parse(STORE).unwrap();let(s,a)=z.targets(STORE).unwrap();assert_eq!(s.unwrap(),V300);assert_eq!(a.unwrap(),ACCOUNT);assert_eq!(z.entries.len(),3);}
#[test]fn zip_targets_deflate_descriptor(){let z=ZipIndex::parse(ZIP).unwrap();let(s,a)=z.targets(ZIP).unwrap();assert_eq!(s.unwrap(),V300);assert_eq!(a.unwrap(),ACCOUNT);assert!(z.entries.iter().all(|e|e.flags&8!=0));}
#[test]fn zip_crc_non_target(){let z=ZipIndex::parse(STORE).unwrap();let mut b=STORE.to_vec();b[z.entries[2].compressed.start]^=1;assert!(ZipIndex::parse(&b).unwrap().targets(&b).is_err());}
#[test]fn zip_truncated(){assert!(ZipIndex::parse(&ZIP[..ZIP.len()-1]).is_err());}
#[test]fn zip_duplicate_local(){let z=ZipIndex::parse(STORE).unwrap();let mut b=STORE.to_vec();let a=z.entries[0].local.start as u32;let p=z.entries[1].central.start+42;b[p..p+4].copy_from_slice(&a.to_le_bytes());assert!(ZipIndex::parse(&b).is_err());}
#[test]fn zip_traversal(){let z=ZipIndex::parse(STORE).unwrap();let mut b=STORE.to_vec();let e=&z.entries[2];b[e.central.start+46..e.central.start+49].copy_from_slice(b"../");b[e.local.start+30..e.local.start+33].copy_from_slice(b"../");assert!(ZipIndex::parse(&b).is_err());}
#[test]fn zip_descriptor_bad(){let z=ZipIndex::parse(ZIP).unwrap();let mut b=ZIP.to_vec();let p=z.entries[0].local.end-1;b[p]^=1;assert!(ZipIndex::parse(&b).is_err());}
#[test]fn account_exact_spans(){let a=read_account(ACCOUNT).unwrap();assert_eq!(a.achievements.len(),1);assert_eq!(a.counters.len(),1);let r=&a.achievements[0];assert_eq!(&ACCOUNT[r.fields[0].clone()],b"true");assert_eq!(&ACCOUNT[r.fields[1].clone()],b"2");assert_eq!(&ACCOUNT[r.fields[2].clone()],b"\"2024-02-29T12:34:56.1234567Z\"");assert_eq!(&ACCOUNT[a.counters[0].field.clone()],b"-1.25");}
#[test]fn account_duplicate_escaped(){assert!(read_account(br#"{"Achievements":{},"\u0041chievements":{},"Counters":{}}"#).is_err());}
#[test]fn account_duplicate_nested(){assert!(read_account(br#"{"Achievements":{},"Counters":{},"Unknown":{"x":1,"x":2}}"#).is_err());}
#[test]fn account_case_duplicate(){let s=br#"{"Achievements":{},"Counters":{"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa":{"CurrentValue":1},"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA":{"CurrentValue":2}}}"#;assert!(read_account(s).is_err());}
#[test]fn account_invalid_date(){let s=std::str::from_utf8(ACCOUNT).unwrap().replace("2024-02-29","2023-02-29");assert!(read_account(s.as_bytes()).is_err());}
#[test]fn account_inconsistent(){let s=std::str::from_utf8(ACCOUNT).unwrap().replace("\"IsComplete\":true","\"IsComplete\":false");assert!(read_account(s.as_bytes()).is_err());}
#[test]fn account_invalid_number(){let s=std::str::from_utf8(ACCOUNT).unwrap().replace("\"CurrentValue\":2","\"CurrentValue\":1e999");assert!(read_account(s.as_bytes()).is_err());}
#[test]fn account_unknown_exact_numeric(){let a=br#"{"Achievements":{},"Counters":{},"x":18446744073709551615,"y":"\ud83d\ude00"}"#;assert!(read_account(a).is_ok());}
#[test]fn session_open_both(){let mut s=new();let r=open(&mut s,1,InputKind::Zip,ZIP);let Payload::Opened(m)=r.result.unwrap()else{panic!()};assert_eq!(r.stamp.source,Some(sha256(ZIP)));assert_eq!(r.stamp.generation,1);assert_eq!(r.stamp.revision,0);assert_eq!(m.counts[4..6],[1,1]);assert!(!m.writer_enabled);}
#[test]fn session_switch_stale_a(){let mut s=new();let a=open(&mut s,1,InputKind::Slot,V300).stamp;let b=open(&mut s,2,InputKind::Slot,V301).stamp;assert_ne!(a.source,b.source);assert_eq!(b.generation,a.generation+1);assert_eq!(s.dispatch(Request{id:3,expected:a,command:Command::Summary}).result,Err(SessionError::Stale));assert_eq!(s.stamp(),b);}
#[test]fn session_failed_open_atomic(){let mut s=new();let a=open(&mut s,1,InputKind::Slot,V300).stamp;assert!(open(&mut s,2,InputKind::Slot,b"bad").result.is_err());assert_eq!(s.stamp(),a);assert_eq!(send(&mut s,2,Command::Summary).result,Err(SessionError::Replay));assert!(send(&mut s,3,Command::Summary).result.is_ok());}
#[test]fn session_replay_close(){let mut s=new();let a=open(&mut s,1,InputKind::Slot,V300).stamp;let c=send(&mut s,2,Command::Close);assert_eq!(c.stamp.source,None);assert_eq!(c.stamp.generation,2);assert_eq!(send(&mut s,2,Command::Close).result,Err(SessionError::Replay));assert_eq!(s.dispatch(Request{id:3,expected:a,command:Command::Summary}).result,Err(SessionError::Stale));assert_eq!(send(&mut s,4,Command::Summary).result,Err(SessionError::NoOpen));}
#[test]fn session_foreign_not_poison(){let mut s=new();let mut st=s.stamp();st.runtime=[4;16];assert_eq!(s.dispatch(Request{id:u64::MAX,expected:st,command:Command::Close}).result,Err(SessionError::Foreign));assert!(open(&mut s,1,InputKind::Account,ACCOUNT).result.is_ok());}
#[test]fn session_revision_and_hash_cas(){let mut s=new();let st=open(&mut s,1,InputKind::Slot,V300).stamp;let mut wrong=st;wrong.revision=1;assert_eq!(s.dispatch(Request{id:2,expected:wrong,command:Command::Summary}).result,Err(SessionError::Stale));wrong=st;wrong.source=Some([0;32]);assert_eq!(s.dispatch(Request{id:3,expected:wrong,command:Command::Summary}).result,Err(SessionError::Stale));assert_eq!(s.stamp(),st);}
#[test]fn session_pages_and_missing(){let mut s=new();open(&mut s,1,InputKind::Account,ACCOUNT);let r=send(&mut s,2,Command::IndexPage{domain:Domain::AccountAchievement,offset:0,limit:1});let Payload::Page(p)=r.result.unwrap()else{panic!()};assert_eq!(p.total,1);assert_eq!(p.rows.len(),1);let p=send(&mut s,3,Command::IndexPage{domain:Domain::AccountAchievement,offset:1,limit:1});assert!(matches!(p.result,Ok(Payload::Page(Page{rows,..})) if rows.is_empty()));assert_eq!(send(&mut s,4,Command::IndexPage{domain:Domain::SlotAchievement,offset:0,limit:1}).result,Err(SessionError::NoDomain));}
#[test]fn session_page_caps(){let mut s=new();open(&mut s,1,InputKind::Slot,V300);for (id,offset,limit) in [(2,0,0),(3,0,PAGE_LIMIT+1),(4,u32::MAX,1)]{assert_eq!(send(&mut s,id,Command::IndexPage{domain:Domain::SlotAchievement,offset,limit}).result,Err(SessionError::Range));}}
#[test]fn session_write_fail_closed(){let mut s=new();let st=open(&mut s,1,InputKind::Zip,ZIP).stamp;for(i,c)in [Command::Plan,Command::Preview,Command::Apply,Command::Verify,Command::Export,Command::Undo,Command::Redo,Command::Reset].into_iter().enumerate(){assert_eq!(send(&mut s,i as u64+2,c).result,Err(SessionError::Unsupported));assert_eq!(s.stamp(),st);}}
#[test]fn abi_open_summary_page(){let mut s=new();let f=frame(s.stamp(),1,1,&[3]);let r=dispatch_frame(&mut s,&f,Some(ACCOUNT.to_vec())).unwrap();assert_eq!(&r[..4],&MAGIC);assert_eq!(r[77],1);assert_eq!(r[78],1);let f=frame(s.stamp(),2,4,&[5,0,0,0,0,1,0]);let r=dispatch_frame(&mut s,&f,None).unwrap();assert_eq!(&r[77..80],&[1,4,5]);assert!(r.len()<=MAX_REPLY);}
#[test]fn abi_reject_malformed_without_consumption(){let mut s=new();let f=frame(s.stamp(),1,1,&[3]);assert_eq!(dispatch_frame(&mut s,&f,None),Err(SessionError::Protocol));assert!(dispatch_frame(&mut s,&f,Some(ACCOUNT.to_vec())).is_ok());let mut f=frame(s.stamp(),2,3,&[]);f.push(0);assert_eq!(dispatch_frame(&mut s,&f,None),Err(SessionError::Protocol));}
#[test]fn abi_u64_exact_and_replay(){let mut s=new();let id=9_007_199_254_740_993;let f=frame(s.stamp(),id,1,&[3]);let r=dispatch_frame(&mut s,&f,Some(ACCOUNT.to_vec())).unwrap();assert_eq!(u64::from_le_bytes(r[4..12].try_into().unwrap()),id);let f=frame(s.stamp(),id,3,&[]);let r=dispatch_frame(&mut s,&f,None).unwrap();assert_eq!(&r[77..80],&[0,2,0]);}
#[test]fn projection_inventory_missing_and_key0(){use hkia_save_core::{native::index_native,envelope::Version};let base=include_bytes!("fixtures/valid-3.0.1.decoded");let mut b=base.to_vec();assert_eq!(b[3],0x94);b[3]=0x96;b.extend([0x92,1,0x95,7,9,0,3,0xc0,0x92,1,0x92,8,10]);let i=index_native(&b,Version::V301).unwrap();assert_eq!(i.inventory.len(),2);assert_eq!(i.inventory[0].item_id,Some(9));assert_eq!(i.inventory[0].quantity,Some(3));assert_eq!(i.inventory[0].unique_is_nil,Some(true));assert_eq!(i.inventory[1].quantity,None);assert_eq!(i.inventory[1].unique_is_nil,None);assert_eq!(i.deprecated.len(),i.deprecated_count);assert_eq!(i.deprecated.len(),2);for r in &i.deprecated{assert!(r.pair.start<r.value.start&&r.pair.end==r.value.end);}let v=i.collection_version.unwrap();assert!(v.span.start<v.span.end);}
#[test]fn projection_counter_duplicate_guid_details(){use hkia_save_core::projection::{DetailKind,DetailRow,detail_page};let slot=hkia_save_core::read_slot(include_bytes!("fixtures/counted-guid-duplicates-and-time.bin")).unwrap();let p=detail_page(&slot,DetailKind::CounterGuids,1,0,2).unwrap();assert_eq!(p.total,3);assert_eq!(p.rows.len(),2);let (DetailRow::Guid{words:a,span:x},DetailRow::Guid{words:b,span:y})=(&p.rows[0],&p.rows[1])else{panic!()};assert_eq!(a,b);assert_ne!(x,y);let p=detail_page(&slot,DetailKind::CounterValues,1,1,1).unwrap();assert!(matches!(&p.rows[0],DetailRow::Text{utf8_len:1,..}));}
#[test]fn projection_null_counted_values(){use hkia_save_core::projection::{DetailKind,detail_page};let s=hkia_save_core::read_slot(V301).unwrap();let p=detail_page(&s,DetailKind::CounterValues,1,0,1).unwrap();assert_eq!(p.total,0);assert_eq!(p.is_null,matches!(&s.index.counters[0].state,hkia_save_core::native::ModelState::Counter{counted_values:None,..}));assert!(detail_page(&s,DetailKind::CounterValues,1,1,1).is_err());}
#[test]fn projection_celebration_lazy_preserves_order(){use hkia_save_core::{projection::{DetailKind,DetailRow,detail_page},native::index_native,envelope::Version};let mut s=hkia_save_core::read_slot(V301).unwrap();let mut b=s.envelope.decoded.clone();b[3]=0x95;b.extend([0x92,8,0x92,4,0x92,1,2,3,4,1,2,3,4]);s.index=index_native(&b,Version::V301).unwrap();s.envelope.decoded=b;let p=detail_page(&s,DetailKind::CelebrationGuids,4,1,1).unwrap();assert_eq!(p.total,2);assert!(matches!(&p.rows[0],DetailRow::Guid{words:[1,2,3,4],..}));}
#[test]fn abi_collection_exact_i64(){let mut s=new();open(&mut s,1,InputKind::Slot,include_bytes!("fixtures/exact-ticks-multiblock.bin"));let f=frame(s.stamp(),2,4,&[3,0,0,0,0,3,0]);let r=dispatch_frame(&mut s,&f,None).unwrap();assert_eq!(r[90],3);assert_eq!(i64::from_le_bytes(r[95..103].try_into().unwrap()),i64::MIN);assert_eq!(i64::from_le_bytes(r[124..132].try_into().unwrap()),9_007_199_254_740_993);}
#[test]fn zip_reject_budget_and_zip64(){let z=ZipIndex::parse(STORE).unwrap();let mut b=STORE.to_vec();let at=z.entries[0].central.start+24;b[at..at+4].copy_from_slice(&(26u32*1024*1024).to_le_bytes());assert!(ZipIndex::parse(&b).is_err());b[at..at+4].copy_from_slice(&u32::MAX.to_le_bytes());assert!(ZipIndex::parse(&b).is_err());}
#[test]fn zip_reject_encrypted_and_local_mismatch(){let z=ZipIndex::parse(STORE).unwrap();let mut b=STORE.to_vec();let at=z.entries[0].central.start+8;b[at..at+2].copy_from_slice(&1u16.to_le_bytes());assert!(ZipIndex::parse(&b).is_err());let mut b=STORE.to_vec();let at=z.entries[0].local.start+8;b[at..at+2].copy_from_slice(&8u16.to_le_bytes());assert!(ZipIndex::parse(&b).is_err());}
#[test]fn account_depth_bound(){let mut s=String::from("{\"Achievements\":{},\"Counters\":{},\"x\":");s.push_str(&"[".repeat(65));s.push_str("null");s.push_str(&"]".repeat(65));s.push('}');assert_eq!(read_account(s.as_bytes()).unwrap_err(),hkia_save_core::Error::Budget);}
#[test]fn account_invalid_surrogate_and_trailing(){assert!(read_account(br#"{"Achievements":{},"Counters":{},"x":"\ud800"}"#).is_err());assert!(read_account(br#"{"Achievements":{},"Counters":{}} null"#).is_err());}
#[test]fn session_bad_zip_keeps_old_account(){let mut s=new();let st=open(&mut s,1,InputKind::Account,ACCOUNT).stamp;let mut raw=ZIP.to_vec();raw.pop();assert!(open(&mut s,2,InputKind::Zip,&raw).result.is_err());assert_eq!(s.stamp(),st);}
